//! Explicit baseline update delivery on the existing bounded report framing.
use super::*;use dq_analyze::native_baseline_update_wire::{Schema,Terminal as BaselineTerminal};
#[derive(Debug)]struct DeliveryFailure{committed:usize,generation_committed:bool,primary:io::Error}
impl std::fmt::Display for DeliveryFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"native baseline update {} file(s) committed, GEN committed={}; delivery failed: {}",self.committed,self.generation_committed,self.primary)}}impl Error for DeliveryFailure{fn source(&self)->Option<&(dyn Error+'static)>{Some(&self.primary)}}
fn delivery(primary:io::Error,n:usize,g:bool)->io::Error{io::Error::new(primary.kind(),DeliveryFailure{committed:n,generation_committed:g,primary})}
fn convert(e:Box<dyn Error>)->io::Error{match e.downcast::<io::Error>(){Ok(e)=>*e,Err(e)=>io::Error::other(e.to_string())}}
pub(crate)fn send_baseline_update(stream:&mut impl Write,staged:crate::runner_host::baseline_update::Staged)->Result<(),SendFailure>{
 let crate::runner_host::baseline_update::Staged{completed,diagnostics,report,_spool_credit}=staged;let n=completed.outcome.committed_files;let g=completed.outcome.generation_committed;
 let before=|e|SendFailure::BeforePublication(delivery(e,n,g));completed.inputs.require_report_current(&completed.project).map_err(convert).map_err(before)?;
 let count=|n:usize|u64::try_from(n).map_err(|_|io::Error::from(io::ErrorKind::OutOfMemory));
 let terminal=BaselineTerminal{schema:Schema::V2,complete:true,full_policy_parity:false,root:completed.root.clone(),mode:completed.mode,no_gen:completed.no_gen,generation_committed:g,selection:completed.selection,selected:count(completed.selected).map_err(before)?,registered:count(completed.outcome.registered).map_err(before)?,committed_files:count(n).map_err(before)?,frame:completed.frame,diagnostics:diagnostics.as_ref().map(seal_of),report:seal_of(&report)};
 terminal.require(&completed.root,completed.mode,completed.no_gen,completed.selection).map_err(before)?;encode_header(&terminal).map_err(before)?;
 let result=(||{control::checkpoint()?;if let Some(stage)=diagnostics{stage.publish(&mut FragmentWriter{stream:&mut *stream,channel:Channel::Diagnostics,sequence:0,offset:0})?;}report.publish(&mut FragmentWriter{stream:&mut *stream,channel:Channel::Report,sequence:0,offset:0})?;completed.inputs.require_report_current(&completed.project).map_err(convert)?;control::checkpoint()?;protocol::send(stream,&SendReply::BaselineUpdateFinished(terminal))})();result.map_err(|e|SendFailure::AfterPublication(delivery(e,n,g)))
}
pub(crate)struct DeliveredBaseline{terminal:BaselineTerminal,diagnostics:Option<Verified>,report:Verified}
impl DeliveredBaseline{pub(crate)fn publish(self,output:&mut impl Write)->io::Result<()>{let n=usize::try_from(self.terminal.committed_files).map_err(|_|invalid("baseline commit count overflow"))?;let g=self.terminal.generation_committed;let result=(||{let(header,length)=encode_header(&self.terminal)?;output.write_all(&header[..length])?;if let Some(d)=self.diagnostics{d.publish(output)?;}self.report.publish(output)})();result.map_err(|e|delivery(e,n,g))}}
pub(crate)fn receive_baseline_update(stream:&mut impl Read,cache:&Path,root:&Path,mode:dq_analyze::native_baseline_update_wire::Mode,no_gen:bool,selection:dq_analyze::full_registry_check_selection_wire::SelectionBinding)->Result<DeliveredBaseline,Box<dyn Error>>{
 let(mut accepted,mut diagnostics,mut report)=(false,Collector::default(),Collector::default());loop{control::checkpoint()?;match protocol::receive_bounded::<ReceiveReply>(stream,protocol::MAX_FRAME)?{
 ReceiveReply::Accepted if !accepted=>accepted=true,ReceiveReply::Rejected(e)if diagnostics.next==0&&report.next==0=>return Err(RequestFailure{kind:e.kind,message:e.message}.into()),
 ReceiveReply::SelectedReportFragment(f)if accepted=>match f.channel{Channel::Diagnostics=>diagnostics.push(cache,&f)?,Channel::Report=>report.push(cache,&f)?,_=>return Err(invalid("baseline received unrelated report channel").into())},
 ReceiveReply::BaselineUpdateFinished(terminal)if accepted=>{terminal.require(root,mode,no_gen,selection)?;require_end(stream)?;let diagnostics=diagnostics.finish(terminal.diagnostics)?;let report=report.finish(Some(terminal.report))?.ok_or_else(||invalid("baseline terminal lacks actual report"))?;return Ok(DeliveredBaseline{terminal,diagnostics,report})},_=>return Err(invalid("unexpected baseline transport frame").into())}}}
